import{_ as e,o as i,c as a,a2 as r}from"./chunks/framework.CdvW4CUT.js";const c=JSON.parse('{"title":"主伺服","description":"主伺服的相關介紹。","frontmatter":{"title":"主伺服","description":"主伺服的相關介紹。"},"headers":[],"relativePath":"server/sv/index.md","filePath":"server/sv.md"}'),t={name:"server/sv/index.md"};function o(s,l,h,d,u,n){return i(),a("div",null,[...l[0]||(l[0]=[r('<h1 id="主伺服-sv" tabindex="-1">主伺服 sv <a class="header-anchor" href="#主伺服-sv" aria-label="Permalink to &quot;主伺服 sv&quot;">​</a></h1><p><font size="4" color="green"><b>玩家建築蓋家的地方</b></font></p><ul><li>禁止蓋生怪塔及任何耗費大量實體或資源的設施 <ul><li>如有此需要，請前往<a href="/server/mh/">設施服(mh)</a></li></ul></li><li>若需採集資源，建議前往<a href="/server/res/">資源服(res)</a></li></ul><h2 id="現有分流" tabindex="-1">現有分流 <a class="header-anchor" href="#現有分流" aria-label="Permalink to &quot;現有分流&quot;">​</a></h2><ul><li>主一(sv1)</li><li>主二(sv2)</li><li>主三(sv3) <ul><li><a href="/donate/">贊助玩家</a>或被贊助玩家邀請才可進入</li></ul></li></ul><h2 id="前往方式" tabindex="-1">前往方式 <a class="header-anchor" href="#前往方式" aria-label="Permalink to &quot;前往方式&quot;">​</a></h2><ul><li>從<a href="/server/Lobby/">大廳服(Lobby)</a>的各分流傳送門前往</li><li>使用<code>/home</code>或<code>/back</code>傳送到位於該分流的紀錄點</li></ul><h2 id="分流設定" tabindex="-1">分流設定 <a class="header-anchor" href="#分流設定" aria-label="Permalink to &quot;分流設定&quot;">​</a></h2><h3 id="基本設定" tabindex="-1">基本設定 <a class="header-anchor" href="#基本設定" aria-label="Permalink to &quot;基本設定&quot;">​</a></h3><ul><li>地圖防爆、防燒</li><li>防噴裝、死亡扣除部分經驗 <ul><li>死亡時扣除5等 <ul><li>玩家經驗等級在10等以下時不扣除經驗</li></ul></li></ul></li></ul><h3 id="特殊設定" tabindex="-1">特殊設定 <a class="header-anchor" href="#特殊設定" aria-label="Permalink to &quot;特殊設定&quot;">​</a></h3><ul><li>關閉生怪磚功能</li><li>生怪效率調降</li><li>村民不會被殭屍攻擊/感染</li><li>終界使者不會撿起方塊</li><li>無法正常觸發突襲 <ul><li>需使用<a href="/feature/sp_tool/">1450呼叫器</a></li><li>身上帶有不祥之兆效果進入村莊範圍會被系統隱藏 <ul><li>隱藏時仍會計算效果時間</li><li>離開村莊範圍後效果會正常顯示</li><li><font color="red"><b>效果隱藏時請不要切換分流或登出，效果會被系統清除</b></font></li></ul></li></ul></li><li>無法召喚終界龍 <ul><li>請前往<a href="/server/res/">資源服(res)</a></li></ul></li><li>不會生成任何魚類 <ul><li>請前往<a href="/server/res/">資源服(res)</a></li></ul></li><li>不會生成夜魅 <ul><li>請前往<a href="/server/res/">資源服(res)</a></li></ul></li><li>部分生物有繁殖限制 <ul><li>牛、豬：10格內小於10隻才可繁殖</li></ul></li><li>無法繁殖悅靈 <ul><li>請使用<a href="/feature/bs/">/bs選單</a>購買生怪蛋</li></ul></li><li>無法繁殖村民 <ul><li>請前往<a href="/server/mh/">設施服(mh)</a></li></ul></li><li>無法繁殖界伏蚌 <ul><li>請前往<a href="/server/mh/">設施服(mh)</a></li></ul></li><li>無法使用發射器剪羊毛 <ul><li>請前往<a href="/server/mh/">設施服(mh)</a></li></ul></li><li>伏聆觸媒不會蔓延 <ul><li>請前往<a href="/server/res/">資源服(res)</a></li></ul></li><li>無法挖掘<b>地獄</b>的遠古遺骸 <ul><li>請前往<a href="/server/res/">資源服(res)</a></li><li><font color="red"><b>請不要在地獄放遠古遺骸，挖掘時會被系統清除</b></font></li></ul></li><li>原木剝皮/銅塊除蠟需使用有絲綢之觸附魔的鑽石/獄髓斧 <ul><li><a href="/server/res/">資源服(res)</a>無此限制</li><li>單純對銅塊除鏽可使用任意的斧頭</li></ul></li></ul><h3 id="邊界大小" tabindex="-1">邊界大小 <a class="header-anchor" href="#邊界大小" aria-label="Permalink to &quot;邊界大小&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分流</th><th>主世界</th><th>地獄</th><th>終界</th></tr></thead><tbody><tr><td>主一(sv1)</td><td>+-60000</td><td>+-7500</td><td>+-10000</td></tr><tr><td>主二(sv2)</td><td>+-36000</td><td>+-8000</td><td>+-12000</td></tr><tr><td>主三(sv3)</td><td>+-28000</td><td>+-8000</td><td>+-12000</td></tr></tbody></table><h2 id="切換世界-分流方式" tabindex="-1">切換世界/分流方式 <a class="header-anchor" href="#切換世界-分流方式" aria-label="Permalink to &quot;切換世界/分流方式&quot;">​</a></h2><h3 id="切換世界" tabindex="-1">切換世界 <a class="header-anchor" href="#切換世界" aria-label="Permalink to &quot;切換世界&quot;">​</a></h3><ul><li>前往地獄請自行找地方蓋地獄門</li><li>前往終界請輸入<code>/spawn</code>回到分流重生點後由傳送門前往</li></ul><h3 id="切換分流" tabindex="-1">切換分流 <a class="header-anchor" href="#切換分流" aria-label="Permalink to &quot;切換分流&quot;">​</a></h3><ul><li>前往<a href="/server/Lobby/">大廳服(Lobby)</a><ul><li>輸入<code>bs</code>後點選指南針前往</li></ul></li><li>前往對應的<a href="/server/mh/">設施服(mh)</a>(主一/設一 主二/設二 主三/設三) <ul><li>輸入<code>/spawn</code>回到分流重生點後由傳送門前往</li><li>輸入<code>bs</code>後點選左上角按鈕前往</li></ul></li><li>前往其他分流 商店街 美術館 <ul><li>請切換至<a href="/server/Lobby/">大廳服(Lobby)</a>後由各分流傳送門前往</li></ul></li></ul>',19)])])}const f=e(t,[["render",o]]);export{c as __pageData,f as default};
